import { Component, computed, input, model, output, signal } from '@angular/core';
import { TablerIconComponent, IconSelector, IconSearch, IconX } from '@tabler/icons-angular';

/** Tài khoản đang đăng nhập — hiện ở khối user cuối side nav (mặc định). */
export interface HrmSideNavUser {
  name: string;
  email?: string;
  /** URL ảnh; bỏ trống dùng chữ viết tắt. */
  avatar?: string;
  /** Chữ viết tắt (bỏ trống tự suy từ name). */
  initials?: string;
}

export interface HrmNavItem {
  key: string;
  label: string;
  /** Tabler icon object (mode object). */
  icon?: unknown;
  route?: string;
  children?: HrmNavItem[];
  /** Từ khoá liên quan để tìm kiếm (ngoài label) — VD Button: ['nút','bấm','action']. */
  keywords?: string[];
  /** Badge đếm/trạng thái (pill primary): "12", "New"… */
  badge?: string | number;
  /** Nội dung phụ căn phải, chữ mờ (VD "8 thành viên"). */
  trailing?: string;
  disabled?: boolean;
}
export interface HrmNavSection {
  /** Tiêu đề nhóm (ẩn khi collapsed). */
  header?: string;
  items: HrmNavItem[];
}

/** hrm-side-nav — điều hướng dọc app-shell. Header = logo (icon+chữ) + actions (chuông) +
 *  nút thu gọn (hamburger) cạnh actions. Section có tiêu đề, item icon+nhãn, mục chọn = pill.
 *  Nhóm con: expand → mở/gập inline; collapsed → hover ra FLYOUT. Collapsed = rail chỉ icon,
 *  hover logo hiện nút mở rộng. Toàn token → tự bám Light/Dark/brand.
 *  <hrm-side-nav [sections]="nav" [(collapsed)]="col" [logoSrc]="..." [logoMarkSrc]="..."
 *                [toggleIcon]="menu" [caretIcon]="chev"><button snActions>...chuông...</button></hrm-side-nav> */
@Component({
  selector: 'hrm-side-nav',
  imports: [TablerIconComponent],
  template: `
    <nav class="sn" [class.is-collapsed]="collapsed()" [attr.aria-label]="ariaLabel() || null">

      <!-- Header -->
      @if (!collapsed()) {
        <div class="sn-brand">
          @if (logoSrc()) { <img class="sn-brand-logo" [src]="logoSrc()" alt="logo" /> }
          <div class="sn-brand-act">
            <ng-content select="[snActions]" />
            @if (toggleIcon()) {
              <button type="button" class="sn-iconbtn" aria-label="Thu gọn" (click)="collapsed.set(true)">
                <tabler-icon [icon]="$any(toggleIcon())" [size]="20" [stroke]="iconStroke()" />
              </button>
            }
          </div>
        </div>
      } @else {
        <div class="sn-brand-mark">
          @if (logoMarkSrc() || logoSrc()) { <img class="sn-mark-logo" [src]="logoMarkSrc() || logoSrc()" alt="logo" /> }
          @if (expandIcon() || toggleIcon()) {
            <button type="button" class="sn-expand" aria-label="Mở rộng" (click)="collapsed.set(false)">
              <tabler-icon [icon]="$any(expandIcon() || toggleIcon())" [size]="20" [stroke]="iconStroke()" />
            </button>
          }
        </div>
      }

      <div class="sn-head"><ng-content select="[snHead]" /></div>

      @if (searchable() && !collapsed()) {
        <div class="sn-search">
          <tabler-icon class="sn-search-ic" [icon]="$any(searchIcon)" [size]="16" [stroke]="iconStroke()" />
          <input class="sn-search-in" type="text" [value]="query()" (input)="onSearch($event)"
            [attr.placeholder]="searchPlaceholder() || null" [attr.aria-label]="searchPlaceholder() || null" />
          @if (query()) {
            <button type="button" class="sn-search-clr" (click)="clearSearch()" [attr.aria-label]="clearLabel() || null">
              <tabler-icon [icon]="$any(clearIcon)" [size]="14" [stroke]="iconStroke()" />
            </button>
          }
        </div>
      }

      <div class="sn-scroll">
      @for (sec of displaySections(); track $index) {
        <div class="sn-sec">
          @if (sec.header && !collapsed()) { <div class="sn-header">{{ sec.header }}</div> }
          @for (it of sec.items; track it.key) {
            @if (it.children?.length) {
              <div class="sn-group" (mouseenter)="positionFlyout($event)">
                <button type="button" class="sn-item sn-parent" [class.is-open]="isOpen(it.key)"
                  [class.has-active]="parentHasSelected(it)"
                  [disabled]="it.disabled ?? false" [attr.title]="collapsed() ? it.label : null"
                  [attr.aria-haspopup]="collapsed() ? 'menu' : null"
                  [attr.aria-expanded]="collapsed() ? null : isOpen(it.key)"
                  (click)="parentClick(it)">
                  @if (it.icon) { <tabler-icon class="sn-ic" [icon]="$any(it.icon)" [size]="20" [stroke]="iconStroke()" /> }
                  <span class="sn-label">{{ it.label }}</span>
                  @if (!collapsed() && caretIcon()) { <tabler-icon class="sn-caret" [icon]="$any(caretIcon())" [size]="16" [stroke]="iconStroke()" /> }
                </button>
                @if (!collapsed() && isOpen(it.key)) {
                  <div class="sn-children">
                    @for (c of it.children!; track c.key) {
                      <button type="button" class="sn-item sn-child" [class.is-active]="c.key === selectedKey()"
                        [disabled]="c.disabled ?? false" (click)="pick(c)">
                        <span class="sn-label">{{ c.label }}</span>
                        @if (c.trailing) { <span class="sn-trail">{{ c.trailing }}</span> }
                        @if (c.badge != null) { <span class="sn-badge">{{ c.badge }}</span> }
                      </button>
                    }
                  </div>
                }
                @if (collapsed()) {
                  <div class="sn-flyout" role="menu" [attr.aria-label]="it.label"
                    [style.top.px]="flyoutAt()?.top" [style.left.px]="flyoutAt()?.left">
                    <div class="sn-flyout-h">{{ it.label }}</div>
                    @for (c of it.children!; track c.key) {
                      <button type="button" class="sn-fly-item" role="menuitem" [class.is-active]="c.key === selectedKey()"
                        [disabled]="c.disabled ?? false" (click)="pick(c)">
                        {{ c.label }}
                        @if (c.badge != null) { <span class="sn-badge">{{ c.badge }}</span> }
                      </button>
                    }
                  </div>
                }
              </div>
            } @else {
              <button type="button" class="sn-item" [class.is-active]="it.key === selectedKey()"
                [disabled]="it.disabled ?? false" [attr.title]="collapsed() ? it.label : null"
                (click)="pick(it)">
                @if (it.icon) { <tabler-icon class="sn-ic" [icon]="$any(it.icon)" [size]="20" [stroke]="iconStroke()" /> }
                <span class="sn-label">{{ it.label }}</span>
                @if (!collapsed()) {
                  @if (it.trailing) { <span class="sn-trail">{{ it.trailing }}</span> }
                  @if (it.badge != null) { <span class="sn-badge">{{ it.badge }}</span> }
                }
              </button>
            }
          }
        </div>
      }

      @if (searchable() && !collapsed() && query().trim() && !displaySections().length) {
        <div class="sn-empty">{{ searchEmpty() }}</div>
      }
      </div>

      <div class="sn-foot">
        @if (user(); as u) {
          <button type="button" class="sn-user" (click)="userClick.emit()" [attr.aria-label]="u.name">
            <span class="sn-uav">
              @if (u.avatar) { <img [src]="u.avatar" alt="" /> } @else { {{ u.initials || initialsOf(u.name) }} }
            </span>
            @if (!collapsed()) {
              <span class="sn-uinfo">
                <span class="sn-uname">{{ u.name }}</span>
                @if (u.email) { <span class="sn-umail">{{ u.email }}</span> }
              </span>
              @if (showSwitchAccount()) {
                <span class="sn-switch" role="button" [attr.aria-label]="switchLabel() || null"
                  (click)="$event.stopPropagation(); switchAccount.emit()">
                  <tabler-icon [icon]="$any(switchIcon() ?? selectorIcon)" [size]="18" [stroke]="iconStroke()" />
                </span>
              }
            }
          </button>
        }
        <ng-content select="[snFooter]" />
      </div>
    </nav>
  `,
  host: { class: 'hrm-side-nav' },
  styles: [`
:host { display: block; }
.sn {
  position: relative;
  display: flex; flex-direction: column; gap: 4px;
  width: 264px; padding: 12px 10px;
  background: var(--bg-surface); border-right: 1px solid var(--border-sub);
  font-family: var(--font-sans); overflow: hidden; min-height: 0;
  transition: width var(--duration-normal, .22s) var(--ease-out, ease);
}
.sn.is-collapsed { width: 72px; padding: 12px 8px; align-items: stretch; }

/* Ghim: brand (top) + foot (bottom) cố định; chỉ .sn-scroll (danh sách nav) cuộn dọc. */
.sn-brand, .sn-brand-mark, .sn-head, .sn-search, .sn-foot { flex: none; }
.sn-scroll { flex: 1 1 auto; min-height: 0; overflow-y: auto; display: flex; flex-direction: column; gap: 4px; }

/* Header — logo + actions + toggle */
.sn-brand {
  display: flex; align-items: center; gap: 8px;
  padding: 4px 6px 12px; margin-bottom: 6px; border-bottom: 1px solid var(--border-soft);
}
.sn-brand-logo { height: 30px; width: auto; flex: 1; min-width: 0; object-fit: contain; object-position: left center; }
.sn-brand-act { display: flex; align-items: center; gap: 2px; flex: none; }
.sn-iconbtn {
  display: grid; place-items: center; width: 34px; height: 34px;
  border: 0; background: transparent; border-radius: var(--radius-md); cursor: pointer; color: var(--text-sub);
}
.sn-iconbtn:hover { background: var(--bg-surface-subtle); color: var(--text-strong); }
/* Collapsed header — mark + hover expand */
.sn-brand-mark {
  position: relative; display: flex; justify-content: center; align-items: center;
  height: 44px; margin-bottom: 8px; padding-bottom: 8px; border-bottom: 1px solid var(--border-soft);
}
.sn-mark-logo { height: 30px; width: auto; transition: opacity var(--duration-fast, .15s) var(--ease-out, ease); }
.sn-expand {
  position: absolute; inset: 0 0 8px 0; margin: auto;
  display: grid; place-items: center; width: 34px; height: 34px;
  border: 1px solid var(--border-sub); background: var(--bg-surface); border-radius: var(--radius-md);
  cursor: pointer; color: var(--text-sub); opacity: 0; transition: opacity var(--duration-fast, .15s) var(--ease-out, ease);
  box-shadow: var(--shadow-regular-xs);
}
.sn-brand-mark:hover .sn-mark-logo { opacity: 0; }
.sn-brand-mark:hover .sn-expand { opacity: 1; }
.sn-expand:hover { background: var(--bg-surface-subtle); color: var(--text-strong); }

.sn-sec { display: flex; flex-direction: column; gap: 2px; }
.sn-sec + .sn-sec { margin-top: 14px; }
.sn-header {
  font-size: var(--fs-11); font-weight: 600; text-transform: uppercase; letter-spacing: 0.04em;
  color: var(--text-soft); padding: 10px 10px 4px;
}
.sn-group { position: relative; }
.sn-item {
  display: flex; align-items: center; gap: 10px; width: 100%;
  padding: 8px 10px; border: 0; background: transparent; cursor: pointer;
  border-radius: var(--radius-lg); text-align: left;
  font-size: var(--fs-14); font-weight: 400; color: var(--text-body); font-family: inherit;
  transition: background var(--duration-fast, .15s) var(--ease-out, ease), color var(--duration-fast, .15s) var(--ease-out, ease);
}
.sn-item:hover:not(:disabled) { background: var(--bg-surface-subtle); color: var(--text-strong); }
.sn-item:disabled { color: var(--text-disabled); cursor: not-allowed; }
.sn-item.is-active {
  background: var(--primary-bg-subtle); color: var(--primary-base); font-weight: 500;
}
/* Hover TRÊN mục đang chọn — đậm hơn 1 nấc để vẫn có phản hồi (không "chết" bằng nền active). */
.sn-item.is-active:hover:not(:disabled) { background: var(--primary-bg-soft); color: var(--primary-base); }
:host-context(.dark) .sn-item.is-active { color: var(--text-strong); }

/* Focus bàn phím — vòng focus rõ trên mọi phần tử bấm được (WCAG 2.4.7). */
.sn-item:focus-visible,
.sn-fly-item:focus-visible,
.sn-iconbtn:focus-visible,
.sn-expand:focus-visible,
.sn-user:focus-visible,
.sn-switch:focus-visible,
.sn-search-clr:focus-visible {
  outline: 2px solid var(--primary-focus-ring, var(--primary-base)); outline-offset: 1px;
}

/* Cha (đóng nhóm) chứa mục đang chọn — nhãn đậm + màu để biết trang hiện tại nằm trong nhóm này. */
.sn-parent.has-active:not(.is-open) { color: var(--text-strong); font-weight: 500; }
.sn-parent.has-active:not(.is-open) .sn-ic { color: var(--primary-base); }
.sn-ic { flex: none; }
.sn-label { flex: 1; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.sn-caret { flex: none; color: var(--text-soft); transition: transform var(--duration-fast, .15s) var(--ease-out, ease); }
.sn-parent.is-open .sn-caret { transform: rotate(90deg); }
.sn-children { display: flex; flex-direction: column; gap: 2px; margin: 2px 0 2px 30px; }
.sn-child { padding: 7px 10px; font-weight: 400; }
.sn-badge {
  flex: none; font-size: var(--fs-11); font-weight: 600; line-height: 1;
  padding: 3px 7px; border-radius: var(--radius-full);
  background: var(--primary-bg-soft); color: var(--primary-base);
}
.sn-trail { flex: none; font-size: var(--fs-12); color: var(--text-soft); }
.sn-head { padding: 2px 4px 12px; margin-bottom: 4px; border-bottom: 1px solid var(--border-soft); }
.sn-head:empty { display: none; }

/* Ô tìm kiếm nhóm/component (variant searchable) */
.sn-search {
  display: flex; align-items: center; gap: 8px; margin: 2px 4px 10px; padding: 7px 10px;
  background: var(--bg-surface-subtle); border: 1px solid var(--border-sub); border-radius: var(--radius-lg);
}
.sn-search:focus-within { border-color: var(--primary-base); }
.sn-search-ic { flex: none; color: var(--text-soft); }
.sn-search-in {
  flex: 1; min-width: 0; border: 0; background: transparent; outline: none;
  font-family: inherit; font-size: var(--fs-13); color: var(--text-body);
}
.sn-search-in::placeholder { color: var(--text-soft); }
.sn-search-clr {
  flex: none; display: grid; place-items: center; width: 18px; height: 18px; padding: 0;
  border: 0; background: transparent; cursor: pointer; color: var(--text-soft); border-radius: var(--radius-sm);
}
.sn-search-clr:hover { color: var(--text-strong); background: var(--bg-surface); }
.sn-empty { padding: 16px 12px; font-size: var(--fs-13); color: var(--text-soft); text-align: center; }

/* Flyout nhóm khi collapsed — HOVER icon cha ra popup con (click con để chọn). */
.sn-flyout {
  display: none; position: absolute; left: calc(100% + 8px); top: 0; z-index: 30;
  min-width: 190px; padding: 6px; background: var(--bg-surface);
  border: 1px solid var(--border-sub); border-radius: var(--radius-xl); box-shadow: var(--shadow-regular-md);
}
/* Cầu nối phủ khoảng hở 8px giữa rail và flyout — chuột băng qua không rớt :hover (đóng sớm). */
.sn-flyout::before { content: ''; position: absolute; left: -8px; top: 0; bottom: 0; width: 8px; }
.sn.is-collapsed .sn-group:hover .sn-flyout { display: block; }
.sn-flyout-h { font-size: var(--fs-11); font-weight: 600; text-transform: uppercase; letter-spacing: 0.04em; color: var(--text-soft); padding: 6px 10px 4px; }
.sn-fly-item {
  display: flex; align-items: center; gap: 8px; width: 100%; padding: 7px 10px;
  border: 0; background: transparent; cursor: pointer; border-radius: var(--radius-md);
  font-size: var(--fs-14); color: var(--text-body); font-family: inherit; text-align: left;
}
.sn-fly-item:hover:not(:disabled) { background: var(--bg-surface-subtle); color: var(--text-strong); }
.sn-fly-item.is-active { background: var(--primary-bg-subtle); color: var(--primary-base); }
.sn-fly-item .sn-badge { margin-left: auto; }

/* Footer (khối tài khoản người dùng) — ghim đáy side nav */
.sn-head, .sn-foot { display: flex; }
.sn-foot { padding: 10px 4px 2px; border-top: 1px solid var(--border-soft); }
.sn-foot:empty { display: none; }

/* Khối user mặc định — avatar + tên + email + nút Chuyển tài khoản. */
.sn-user { display: flex; align-items: center; gap: 10px; width: 100%; padding: 6px 8px; border: 0;
  background: transparent; border-radius: var(--radius-lg); cursor: pointer; text-align: left; }
.sn-user:hover { background: var(--bg-surface-subtle); }
.sn-uav { flex: none; display: grid; place-items: center; width: 34px; height: 34px; border-radius: 50%;
  overflow: hidden; background: var(--primary-base); color: var(--text-on-primary, #fff); font-size: var(--fs-13); font-weight: 600; }
.sn-uav img { width: 100%; height: 100%; object-fit: cover; }
.sn-uinfo { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.sn-uname { font-size: var(--fs-14); font-weight: 600; color: var(--text-strong); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.sn-umail { font-size: var(--fs-12); color: var(--text-sub); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.sn-switch { flex: none; display: inline-flex; color: var(--text-soft); padding: 2px; border-radius: var(--radius-sm); }
.sn-switch:hover { color: var(--text-strong); background: var(--bg-surface-subtle); }
.sn.is-collapsed .sn-user { justify-content: center; padding: 6px 0; }

/* Collapsed rail: ẩn nhãn/badge/trail/caret; mục chọn/hover = Ô VUÔNG bao quanh icon (không phải hình chữ nhật) */
.sn.is-collapsed .sn-label,
.sn.is-collapsed .sn-badge,
.sn.is-collapsed .sn-trail,
.sn.is-collapsed .sn-caret { display: none; }
.sn.is-collapsed .sn-item { width: 40px; height: 40px; padding: 0; margin: 0 auto; justify-content: center; gap: 0; }
/* Collapsed: icon CHA chứa mục đang chọn = ô active (định vị "đang ở nhóm này" trên rail). */
.sn.is-collapsed .sn-parent.has-active { background: var(--primary-bg-subtle); }
.sn.is-collapsed .sn-parent.has-active .sn-ic { color: var(--primary-base); }
/* Cha DISABLED: không bung flyout khi hover. */
.sn.is-collapsed .sn-group:has(.sn-parent:disabled):hover .sn-flyout { display: none; }
/* Collapsed: flyout con nằm NGOÀI bề rộng rail → phải bỏ clip overflow để hiện (nhãn đã ẩn nên
   overflow visible không lộ gì; rail icon-only hiếm khi cần cuộn dọc). */
/* Thu gọn: aside cho tràn (không cần), NHƯNG .sn-scroll VẪN cuộn dọc (overflow-y:auto kế thừa
   từ rule gốc) để rail dài hơn màn hình không bị cắt icon dưới. Flyout dùng position:fixed
   (toạ độ set bằng JS khi hover) nên thoát khỏi overflow của .sn-scroll, không bị clip. */
.sn.is-collapsed { overflow: visible; }
.sn.is-collapsed .sn-flyout { position: fixed; }
.sn.is-collapsed .sn-head, .sn.is-collapsed .sn-foot { justify-content: center; padding-left: 0; padding-right: 0; }
  `],
})
export class HrmSideNav {
  readonly sections = input<HrmNavSection[]>([]);
  readonly selectedKey = input<string>('');
  /** Thu gọn (rail). Two-way: nút toggle tự lật; page có thể [(collapsed)]. */
  readonly collapsed = model(false);
  readonly ariaLabel = input('');
  /** Tabler caret icon (object) cho nhóm con. */
  readonly caretIcon = input<unknown>(null);
  /** Ghi đè độ dày nét icon (Tabler stroke) riêng cho side nav. Bỏ trống = theo mặc định toàn hệ thống
   *  (provideTablerIconConfig, đang set 1.5). Đặt số để override, VD [iconStroke]="2". */
  readonly iconStroke = input<number | undefined>(undefined);
  /** Logo đầy đủ (URL) — icon + chữ, hiện khi expand. */
  readonly logoSrc = input('');
  /** Logo mark (URL) — chỉ icon, hiện khi collapsed. */
  readonly logoMarkSrc = input('');
  /** Icon nút THU GỌN (sidebar mũi tên trái) — hiện cạnh actions khi expand. */
  readonly toggleIcon = input<unknown>(null);
  /** Icon nút MỞ RỘNG (sidebar mũi tên phải) — hiện khi hover mark lúc collapsed. Bỏ trống dùng toggleIcon. */
  readonly expandIcon = input<unknown>(null);
  /** Tài khoản đang đăng nhập — hiện khối user mặc định ở cuối side nav (avatar + tên + email + Chuyển tài khoản). */
  readonly user = input<HrmSideNavUser | null>(null);
  /** Hiện nút Chuyển tài khoản (mũi tên đổi) trong khối user. */
  readonly showSwitchAccount = input(true);
  /** Nhãn a11y nút Chuyển tài khoản (i18n, bên gọi cấp). */
  readonly switchLabel = input('');
  /** Icon nút affordance ở khối user (mặc định selector up-down). Đặt = gear (IconSettings) cho kiểu cài đặt. */
  readonly switchIcon = input<unknown>(null);
  /** Bật ô tìm kiếm ở đầu nav — lọc nhóm/component theo label + keywords (không dấu). */
  readonly searchable = input(false);
  /** Placeholder ô tìm kiếm (i18n, bên gọi cấp). */
  readonly searchPlaceholder = input('');
  /** Nhãn a11y nút xoá tìm kiếm (i18n). */
  readonly clearLabel = input('');
  /** Text khi không có kết quả tìm (i18n). */
  readonly searchEmpty = input('');
  readonly itemClick = output<HrmNavItem>();
  /** Bấm vào khối user (mở menu tài khoản). */
  readonly userClick = output<void>();
  /** Bấm nút Chuyển tài khoản. */
  readonly switchAccount = output<void>();
  protected readonly selectorIcon = IconSelector;
  protected readonly searchIcon = IconSearch;
  protected readonly clearIcon = IconX;
  protected readonly query = signal('');

  /** Toạ độ viewport để neo flyout (chế độ thu gọn). Flyout dùng position:fixed nên KHÔNG bị
   *  cắt bởi overflow của .sn-scroll — nhờ đó rail thu gọn có thể cuộn dọc khi nav dài hơn
   *  màn hình mà submenu vẫn tràn ra ngoài được. Chỉ 1 flyout hiện tại 1 thời điểm (:hover). */
  protected readonly flyoutAt = signal<{ top: number; left: number } | null>(null);
  protected positionFlyout(ev: MouseEvent): void {
    const r = (ev.currentTarget as HTMLElement).getBoundingClientRect();
    this.flyoutAt.set({ top: r.top, left: r.right + 8 });
  }

  protected onSearch(e: Event): void { this.query.set((e.target as HTMLInputElement).value); }
  protected clearSearch(): void { this.query.set(''); }

  /** Chuẩn hoá bỏ dấu tiếng Việt để tìm không phân biệt dấu/hoa-thường. */
  private norm(s: string): string {
    return (s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[\u0111]/g, 'd');
  }
  private matchItem(it: HrmNavItem, q: string): boolean {
    if (this.norm(it.label).includes(q)) return true;
    return it.keywords?.some((k) => this.norm(k).includes(q)) ?? false;
  }
  /** Sections sau khi lọc theo query. Query rỗng / không searchable → nguyên bản.
   *  Cha khớp → giữ cả nhóm con; chỉ con khớp → giữ cha + con khớp (tự mở). */
  protected readonly displaySections = computed<HrmNavSection[]>(() => {
    const secs = this.sections();
    if (!this.searchable()) return secs;
    const raw = this.query().trim();
    if (!raw) return secs;
    const q = this.norm(raw);
    const out: HrmNavSection[] = [];
    for (const sec of secs) {
      const headerMatch = sec.header ? this.norm(sec.header).includes(q) : false;
      const items: HrmNavItem[] = [];
      for (const it of sec.items) {
        if (it.children?.length) {
          if (headerMatch || this.matchItem(it, q)) {
            items.push(it);
          } else {
            const kids = it.children.filter((c) => this.matchItem(c, q));
            if (kids.length) items.push({ ...it, children: kids });
          }
        } else if (headerMatch || this.matchItem(it, q)) {
          items.push(it);
        }
      }
      if (items.length) out.push({ ...sec, items });
    }
    return out;
  });

  protected initialsOf(name: string): string {
    const n = (name || '').trim();
    if (!n) return '';
    const p = n.split(/\s+/);
    return ((p[0][0] ?? '') + (p.length > 1 ? p[p.length - 1][0] : '')).toUpperCase();
  }

  private readonly manual = signal<Map<string, boolean>>(new Map());
  private readonly openInit = computed(() => {
    const sel = this.selectedKey();
    const s = new Set<string>();
    for (const sec of this.sections()) {
      for (const it of sec.items) {
        if (it.children?.some((c) => c.key === sel)) s.add(it.key);
      }
    }
    return s;
  });

  /** Nhóm cha có chứa mục con đang được chọn? → hiện dấu định vị (collapsed: icon active;
   *  expanded-đóng: chấm bên phải) để không mất dấu trang hiện tại. */
  protected parentHasSelected(it: HrmNavItem): boolean {
    const sel = this.selectedKey();
    return it.children?.some((c) => c.key === sel) ?? false;
  }
  protected isOpen(key: string): boolean {
    if (this.searchable() && this.query().trim()) return true;
    const m = this.manual().get(key);
    return m !== undefined ? m : this.openInit().has(key);
  }
  protected toggle(key: string): void {
    const m = new Map(this.manual());
    m.set(key, !this.isOpen(key));
    this.manual.set(m);
  }
  /** Bấm mục cha: expand → mở/gập nhóm inline. Collapsed (rail) → KHÔNG làm gì:
   *  flyout con mở bằng HOVER icon cha, chọn con = click item trong flyout (không auto-điều hướng). */
  protected parentClick(it: HrmNavItem): void {
    if (!this.collapsed()) this.toggle(it.key);
  }
  protected pick(it: HrmNavItem): void {
    if (it.disabled) return;
    this.itemClick.emit(it);
  }
}
